begin;

do $$
begin
  if not exists (select 1 from public.carbon_projetos
     where nome ilike '%parakan%' or nome ilike '%awaet%') then
    raise exception 'nenhum projeto Parakana/Awaete em carbon_projetos';
  end if;
end $$;

-- Limpeza da carga anterior: SO linha importada (origem_aba preenchida) e os
-- ciclos da v1. Nada digitado pela tela e tocado.
delete from public.carbon_comprovantes where origem_aba is not null;
delete from public.carbon_prestacao_lancamentos where origem_aba is not null;
