insert into public.carbon_prestacao_lancamentos
  (ciclo_id, grupo_id, aldeia_id, eixo_id, competencia, descricao, valor,
   quantidade, documento, tem_comprovante, observacoes, origem_aba, origem_linha)
select c.id, g.id,
  (select a.id from public.carbon_aldeias a where a.grupo_id = g.id and a.nome = 'PARANOWANA'),
  (select e.id from public.carbon_eixos e where e.projeto_id = g.projeto_id and e.nome = 'Energia'),
  '2024-10-31', '2 Placas Solares', -1700.0, 2.0, null, true, null, 'Extrato', 6
  from public.carbon_ciclos_prestacao c join public.carbon_grupos_comunitarios g on g.id = c.grupo_id where g.chave = 'baixo' and c.nome = 'Outubro 2024 a Abril 2025'
on conflict on constraint carbon_prest_lanc_origem_uq do update set
  valor = excluded.valor, descricao = excluded.descricao,
  tem_comprovante = excluded.tem_comprovante, observacoes = excluded.observacoes,
  atualizado_em = now();
insert into public.carbon_prestacao_lancamentos
  (ciclo_id, grupo_id, aldeia_id, eixo_id, competencia, descricao, valor,
